module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

localparam S0 = 2'b00;
localparam S1 = 2'b01;
localparam S2 = 2'b10;
localparam S3 = 2'b11;

reg [1:0] state, next_state;

always @(*) begin
    case (state)
        S0: begin
            if (data_in == 1'b0) begin
                next_state = S1;
                data_out = 1'b0;
            end else begin
                next_state = S0;
                data_out = 1'b0;
            end
        end
        S1: begin
            if (data_in == 1'b1) begin
                next_state = S2;
                data_out = 1'b0;
            end else begin
                next_state = S1;
                data_out = 1'b0;
            end
        end
        S2: begin
            if (data_in == 1'b0) begin
                next_state = S3;
                data_out = 1'b1;
            end else begin
                next_state = S0;
                data_out = 1'b1;
            end
        end
        S3: begin
            if (data_in == 1'b1) begin
                next_state = S2;
                data_out = 1'b1;
            end else begin
                next_state = S1;
                data_out = 1'b1;
            end
        end
        default: begin
            next_state = S0;
            data_out = 1'b0;
        end
    endcase
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S0;
    end else begin
        state <= next_state;
    end
end

endmodule
